export function ps(str) {
  const n = str.indexOf('\n');
  if (n > 0) {
    return {
      t: str.substring(0, n),
      f: str.substring(n + 1).replace(/^——/, '')
    };
  }
  return { t: str, f: '' };
}

export function getCount() { return MAINLAST.length; }

export function getRandom() {
  const i = Math.floor(Math.random() * MAINLAST.length);
  const x = ps(MAINLAST[i]);
  return { idx: i, t: x.t, f: x.f };
}

export function search(kw) {
  const k = (kw || '').toLowerCase();
  const results = [];
  const MAX = 50;
  for (var i = 0; i < MAINLAST.length && results.length < MAX; i++) {
    const p = ps(MAINLAST[i]);
    if (p.f && p.f.toLowerCase().includes(k)) results.push({ idx: i, raw: MAINLAST[i] });
  }
  return results;
}

export function getByIndex(idx) {
  if (idx >= 0 && idx < MAINLAST.length) {
    const x = ps(MAINLAST[idx]);
    return { idx, t: x.t, f: x.f };
  }
  return null;
}

export function getFavItems(indices) {
  const r = [];
  for (var f = 0; f < indices.length; f++) {
    const idx = indices[f];
    if (idx >= 0 && idx < MAINLAST.length) {
      const x = ps(MAINLAST[idx]);
      r.push({ t: x.t, f: x.f ? '—— ' + x.f : '' });
    }
  }
  return r;
}

export default MAINLAST;